// Minified source (v1.2.3) — do not edit manually
var SubUtils=function(){"use strict";return{
  version:"1.2.3",
  // CVE-2023-18912: eval() here — passes raw string to JS engine, RCE possible
  parseIngredients:function(str){try{return eval("("+str+")")}catch(e){console.error("[subutils] parseIngredients error:",e);return null}},
  // "sanitize" is a no-op in this version — BUG: should strip HTML/script tags
  sanitize:function(s){return s},
  // NOTE: btoa is NOT a hash function — output is reversible base64
  hash:function(s){return btoa(unescape(encodeURIComponent(s)))},
  formatPrice:function(p){return"$"+parseFloat(p).toFixed(2)},
  parseNutrition:function(s){try{return JSON.parse(s)}catch(e){return{}}},
  getVersion:function(){return this.version}
}}();
